(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-418":{scenario:{company:"Sương Mai Skincare",supervisor:{name:"Trần Thu Hà",role:{vi:"Trưởng phòng Truyền thông Số",en:"Head of Digital Communications"}},ref_code:"SM-2611",title:{vi:"Đo đúng tương tác. Xử lý đúng mức độ sự cố.",en:"Measure engagement right. Escalate at the right level."},brief:{vi:"Bạn rà soát báo cáo tuần SM-2611 của fanpage có 150.000 người theo dõi. Bài chiến dịch “Glow Week” đạt tiếp cận 62.500 người với 2.180 cảm xúc, 412 bình luận, 236 chia sẻ và 172 lượt lưu. Cùng tuần, một khách hàng đăng ảnh bị kích ứng da sau khi dùng serum, bài đã có 1.350 lượt chia sẻ. Đối chiếu báo cáo nháp với tài liệu đã duyệt, sửa mức độ sự cố và tỷ lệ tương tác, rồi lập báo cáo có căn cứ.",en:"You are reviewing weekly report SM-2611 for a fan page with 150,000 followers. The “Glow Week” campaign post reached 62,500 people with 2,180 reactions, 412 comments, 236 shares and 172 saves. In the same week a customer posted photos of skin irritation after using the serum, and that post already has 1,350 shares. Compare the draft report with the approved documents, correct the incident severity and the engagement rate, then write an evidence-based report."},reference_title:{vi:"Ma trận sự cố & chuẩn đo lường đã duyệt · SM-2611",en:"Approved incident matrix & metrics standard · SM-2611"},fields:[{id:"INCIDENT_SEV",label:{vi:"Mức độ sự cố của bài kích ứng da",en:"Severity of the skin irritation post"},initial:"SEV-1",expected:"SEV-3",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân loại sự cố mạng xã hội",hint:{vi:"Mọi cáo buộc ảnh hưởng sức khỏe hoặc bài vượt 1.000 lượt chia sẻ phải xếp mức cao nhất và chuyển ngay cho PR, QA.",en:"Any health-related allegation or a post above 1,000 shares goes to the top level and straight to PR and QA."}},{id:"ER_REACH",label:{vi:"Tỷ lệ tương tác theo tiếp cận (%)",en:"Engagement rate by reach (%)"},initial:"2.0",expected:"4.8",reference:"Chuẩn đo lường KPI mạng xã hội",ref_value:{vi:"Tương tác = cảm xúc + bình luận + chia sẻ + lưu; mẫu số là tiếp cận của bài 62.500",en:"Engagements = reactions + comments + shares + saves; the denominator is post reach of 62,500"},hint:{vi:"Bản nháp chia cho số người theo dõi của trang; chuẩn của công ty dùng tiếp cận của từng bài.",en:"The draft divides by page followers; the company standard uses the reach of each post."}}],sop32:{vi:"Tỷ lệ tương tác theo tiếp cận (%) = (cảm xúc + bình luận + chia sẻ + lưu) / tiếp cận của bài x 100, làm tròn 1 chữ số thập phân; không dùng số người theo dõi làm mẫu số.",en:"Engagement rate by reach (%) = (reactions + comments + shares + saves) / post reach x 100, rounded to 1 decimal place; never use followers as the denominator."},context:{label:"BÁO CÁO TUẦN / SM-2611",metrics:[{label:{vi:"Người theo dõi trang",en:"Page followers"},value:"150,000"},{label:{vi:"Tiếp cận bài Glow Week",en:"Glow Week post reach"},value:"62,500"},{label:{vi:"Chia sẻ bài khiếu nại",en:"Complaint post shares"},value:"1,350"}]},crisis:{vi:"Trưởng nhóm kinh doanh nhắn: “Xóa hết bình luận chê, chặn người đăng, rồi dùng mấy tài khoản phụ vào khen sản phẩm cho đẹp trang trước buổi livestream tối nay.”",en:"The sales lead messages you: “Delete all the negative comments, block the poster and use our spare accounts to praise the product so the page looks good before tonight's livestream.”"},options:{safe:{vi:"Không xóa phản ánh hợp lệ, không dùng tài khoản ảo; phản hồi công khai và mời khách nhắn riêng, chuyển SEV-3 cho PR, QA, báo trưởng phòng, hoãn bài quảng bá đến khi có kết luận.",en:"Keep legitimate complaints and use no fake accounts; reply publicly and invite the customer to a private chat, escalate SEV-3 to PR, QA and the manager, and pause promotions until findings are in."},shortcut:{vi:"Xóa bình luận tiêu cực, chặn người đăng và cho tài khoản phụ vào khen để kịp livestream.",en:"Delete the negative comments, block the poster and post praise from spare accounts in time for the livestream."},wait:{vi:"Không phản hồi gì, để bài khiếu nại tự lắng xuống rồi tính sau.",en:"Do not respond at all and let the complaint die down on its own."}},questions:{vi:["Vì sao tỷ lệ tương tác đúng là 4.8% chứ không phải 2.0%? Trình bày tử số, mẫu số bạn đã dùng.","Vì sao bài kích ứng da phải xếp SEV-3? Bạn phối hợp với ai, trong bao lâu để xử lý minh bạch?"],en:["Why is the correct engagement rate 4.8% rather than 2.0%? Show the numerator and denominator you used.","Why must the skin irritation post be rated SEV-3? Whom do you involve, and how fast, to handle it transparently?"]},hints:{vi:["Đặt báo cáo nháp cạnh ma trận sự cố và đánh dấu dòng mức độ đang bị xếp thấp.","Cộng đủ bốn loại tương tác rồi chia cho tiếp cận của bài theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không xóa phản ánh hợp lệ, không dùng tài khoản ảo, sự cố sức khỏe phải báo cáo ngay."],en:["Place the draft report next to the incident matrix and flag the severity line rated too low.","Add all four engagement types, then divide by post reach as set out in SOP 3.2.","Re-read SOP 4.2: keep legitimate complaints, use no fake accounts and escalate health incidents at once."]}},learning:{summary:{vi:"Chuyên viên quản trị mạng xã hội và cộng đồng lập kế hoạch nội dung, vận hành fanpage, nhóm cộng đồng và kênh video ngắn, kiểm duyệt bình luận, chăm sóc khách hàng trực tuyến và đo lường hiệu quả. Nghề tạo ra niềm tin và tương tác thật với thương hiệu, đòi hỏi viết tốt, đọc đúng số liệu, phản ứng nhanh khi có sự cố và tuân thủ quy định về quảng cáo, dữ liệu cá nhân.",en:"A social media and community manager plans content, runs fan pages, community groups and short-video channels, moderates comments, provides online customer care and measures performance. The role builds genuine trust and engagement with the brand and requires strong writing, correct reading of metrics, fast incident response and compliance with advertising and personal data rules."},responsibilities:{vi:["Lập lịch nội dung tháng theo mục tiêu chiến dịch và chân dung khách hàng mục tiêu.","Đăng bài, kiểm duyệt bình luận, trả lời tin nhắn theo kịch bản và thời gian cam kết.","Lắng nghe mạng xã hội để phát hiện sớm khiếu nại, tin đồn và xu hướng thảo luận.","Phân loại, báo cáo và phối hợp xử lý sự cố truyền thông theo ma trận mức độ.","Đo tiếp cận, tương tác, chuyển đổi và lập báo cáo tuần, tháng kèm khuyến nghị."],en:["Build the monthly content calendar from campaign goals and target audience personas.","Publish posts, moderate comments and answer messages within scripted guidelines and response times.","Run social listening to catch complaints, rumours and conversation trends early.","Classify, escalate and coordinate communication incidents using the severity matrix.","Measure reach, engagement and conversion and write weekly and monthly reports with recommendations."]},competencies:[{name:{vi:"Lập kế hoạch nội dung",en:"Content planning"},desc:{vi:"Biến mục tiêu kinh doanh thành trụ cột nội dung, lịch đăng và định dạng phù hợp từng nền tảng.",en:"Turn business goals into content pillars, posting calendars and formats suited to each platform."}},{name:{vi:"Quản trị cộng đồng",en:"Community moderation"},desc:{vi:"Áp dụng quy tắc cộng đồng nhất quán, phản hồi lịch sự và chuyển kênh riêng khi cần thông tin cá nhân.",en:"Apply community rules consistently, reply courteously and move to private channels when personal data is needed."}},{name:{vi:"Xử lý khủng hoảng",en:"Crisis handling"},desc:{vi:"Phân loại mức độ, kích hoạt quy trình báo cáo và đăng phản hồi đã duyệt trong thời gian vàng.",en:"Rate severity, trigger the escalation process and post approved responses within the golden hour."}},{name:{vi:"Phân tích số liệu",en:"Analytics"},desc:{vi:"Đọc đúng chỉ số tiếp cận, tương tác, chuyển đổi và giải thích nguyên nhân thay đổi.",en:"Read reach, engagement and conversion metrics correctly and explain what drives changes."}},{name:{vi:"Đạo đức & tuân thủ",en:"Ethics & compliance"},desc:{vi:"Không dùng tài khoản ảo, không xóa phản ánh hợp lệ, ghi rõ nội dung hợp tác quảng cáo và bảo vệ dữ liệu khách hàng.",en:"Use no fake accounts, keep legitimate complaints, disclose paid partnerships and protect customer data."}}],knowledge:{vi:["Pháp luật về quảng cáo: thông tin quảng cáo phải trung thực, không gây nhầm lẫn; quảng cáo mỹ phẩm không được khiến người dùng hiểu sản phẩm là thuốc.","Quy định về bảo vệ dữ liệu cá nhân: chỉ thu thập thông tin khách hàng khi cần, có sự đồng ý và xử lý qua kênh riêng an toàn.","Quy định về quản lý thông tin trên mạng: không đăng tin sai sự thật, không xúc phạm danh dự tổ chức, cá nhân.","Tiêu chuẩn cộng đồng và chính sách quảng cáo của các nền tảng mạng xã hội.","Mô hình phễu nhận biết, cân nhắc, chuyển đổi, trung thành và chỉ số đo tương ứng.","Nguyên tắc truyền thông khủng hoảng: nhanh, minh bạch, đồng cảm, nhất quán một đầu mối phát ngôn."],en:["Advertising law: advertising must be truthful and not misleading; cosmetics ads must not suggest the product is a medicine.","Personal data protection rules: collect customer data only when needed, with consent, and handle it through secure private channels.","Rules on online information: never post false information or defame organisations or individuals.","Community standards and advertising policies of social media platforms.","The awareness, consideration, conversion and loyalty funnel and the matching metrics.","Crisis communication principles: fast, transparent, empathetic and consistent through a single spokesperson."]},tools:["Bộ công cụ quản lý trang và quảng cáo","Công cụ lắng nghe mạng xã hội","Hộp thư hợp nhất và chatbot","Công cụ thiết kế, dựng video ngắn","Bảng tính và bảng điều khiển báo cáo"],kpis:{vi:["Tỷ lệ tương tác theo tiếp cận của từng bài và trung bình tháng.","Thời gian phản hồi đầu tiên với bình luận, tin nhắn trong giờ làm việc.","Tỷ lệ sự cố được phân loại đúng và chuyển đúng cấp trong thời hạn.","Tỷ lệ thảo luận tích cực (sentiment) và tăng trưởng người theo dõi thực."],en:["Engagement rate by reach per post and as a monthly average.","First response time to comments and messages during working hours.","Share of incidents classified correctly and escalated to the right level on time.","Positive sentiment share and growth of genuine followers."]},day:[{time:"08:30",vi:"Đọc báo cáo lắng nghe mạng xã hội qua đêm, gắn cờ bình luận cần xử lý.",en:"Read the overnight social listening report and flag comments that need action."},{time:"10:00",vi:"Duyệt bài và lịch đăng tuần với nhóm nội dung, kiểm tra thông tin sản phẩm.",en:"Approve posts and the weekly calendar with the content team and check product claims."},{time:"13:30",vi:"Trả lời tin nhắn, kiểm duyệt bình luận và chuyển khiếu nại cho chăm sóc khách hàng.",en:"Answer messages, moderate comments and hand complaints to customer care."},{time:"15:30",vi:"Họp với PR và QA về sự cố đang theo dõi, cập nhật phản hồi đã duyệt.",en:"Meet PR and QA on the open incident and update the approved response."},{time:"17:00",vi:"Cập nhật số liệu chiến dịch và gửi bản tóm tắt cuối ngày.",en:"Update campaign metrics and send the end-of-day summary."}],mistakes:{vi:["Tính tỷ lệ tương tác trên số người theo dõi, khiến bài tốt bị đánh giá thấp và so sánh sai giữa các bài.","Xóa hoặc ẩn bình luận tiêu cực hợp lệ, biến một phản ánh nhỏ thành khủng hoảng lòng tin.","Dùng tài khoản ảo, mua tương tác hoặc không ghi rõ nội dung hợp tác quảng cáo."],en:["Calculating engagement on followers, which undervalues strong posts and distorts comparisons.","Deleting or hiding legitimate negative comments, turning a small complaint into a crisis of trust.","Using fake accounts, buying engagement or failing to disclose paid partnerships."]},career:[{vi:"Nhân viên nội dung mạng xã hội",en:"Social media content executive"},{vi:"Chuyên viên quản trị cộng đồng",en:"Community specialist"},{vi:"Trưởng nhóm mạng xã hội",en:"Social media lead"},{vi:"Trưởng phòng truyền thông số",en:"Head of digital communications"}],glossary:[{term:"Reach",vi:"Số người dùng duy nhất đã nhìn thấy nội dung ít nhất một lần.",en:"The number of unique users who saw the content at least once."},{term:"Engagement rate",vi:"Tỷ lệ tương tác trên tiếp cận hoặc trên lượt hiển thị, theo một định nghĩa thống nhất của doanh nghiệp.",en:"Engagements divided by reach or impressions, using one agreed company definition."},{term:"Social listening",vi:"Theo dõi và phân tích thảo luận về thương hiệu trên mạng để phát hiện xu hướng và rủi ro.",en:"Tracking and analysing online conversations about the brand to spot trends and risks."},{term:"Seeding",vi:"Đưa nội dung vào cộng đồng để khơi gợi thảo luận; chỉ hợp lệ khi minh bạch danh tính, không giả làm khách hàng.",en:"Placing content in communities to spark discussion; acceptable only with a transparent identity, never posing as customers."},{term:"Holding statement",vi:"Thông điệp phản hồi ban đầu đã duyệt, dùng khi sự cố chưa có kết luận.",en:"An approved initial response used while an incident is still under investigation."}],quiz:[{q:{vi:"Một bài có tiếp cận 40.000 người và tổng 1.800 tương tác. Tỷ lệ tương tác theo tiếp cận là bao nhiêu?",en:"A post reached 40,000 people and earned 1,800 engagements. What is the engagement rate by reach?"},options:{vi:["1.8%","4.5%","2.2%","45%"],en:["1.8%","4.5%","2.2%","45%"]},answer:1,explain:{vi:"1.800 / 40.000 x 100 = 4.5%; mẫu số là tiếp cận của bài.",en:"1,800 / 40,000 x 100 = 4.5%; the denominator is post reach."}},{q:{vi:"Trưởng nhóm yêu cầu dùng tài khoản phụ vào khen sản phẩm. Bạn làm gì?",en:"Your lead asks you to praise the product from spare accounts. What do you do?"},options:{vi:["Làm theo vì đối thủ cũng làm","Thuê dịch vụ bình luận bên ngoài","Im lặng, không làm và không báo ai","Từ chối, đề xuất mời khách hàng thật chia sẻ có ghi rõ hợp tác"],en:["Comply because competitors do it","Hire an outside comment service","Stay silent, do nothing and tell no one","Refuse and propose real customers sharing with clear disclosure"]},answer:3,explain:{vi:"Giả danh khách hàng là gian dối với người tiêu dùng; cần từ chối và đề xuất cách minh bạch.",en:"Posing as customers deceives consumers; refuse and propose a transparent alternative."}},{q:{vi:"Holding statement khi sự cố chưa có kết luận nên có nội dung gì?",en:"What should a holding statement contain while an incident is unresolved?"},options:{vi:["Ghi nhận sự việc, đồng cảm, nêu bước đang làm và thời điểm cập nhật","Phủ nhận hoàn toàn để bảo vệ thương hiệu","Cho rằng khách hàng dùng sai cách","Hứa bồi thường ngay mọi yêu cầu"],en:["Acknowledge, show empathy, state next steps and when you will update","Deny everything to protect the brand","Blame the customer for misuse","Promise immediate compensation for any claim"]},answer:0,explain:{vi:"Thông điệp ban đầu cần ghi nhận, đồng cảm và minh bạch về bước tiếp theo, không phủ nhận hay đổ lỗi.",en:"An initial message should acknowledge, empathise and be clear about next steps, without denial or blame."}},{q:{vi:"Loại phản hồi nào nên chuyển sang kênh tin nhắn riêng thay vì trả lời công khai?",en:"Which reply should move to a private message instead of a public answer?"},options:{vi:["Câu hỏi về giờ mở cửa","Lời khen sản phẩm","Khiếu nại cần số điện thoại, mã đơn hàng của khách","Câu hỏi về chương trình khuyến mãi"],en:["A question about opening hours","A compliment on the product","A complaint needing the customer's phone number and order ID","A question about a promotion"]},answer:2,explain:{vi:"Thông tin cá nhân của khách phải được thu thập qua kênh riêng để bảo vệ dữ liệu cá nhân.",en:"Customer personal data must be collected through a private channel to protect it."}}],tools_en:["Page and ads management suite","Social listening tool","Unified inbox and chatbot","Design and short-form video editing tools","Spreadsheets and reporting dashboards"]}}})})(window.KKR);
